window.SCHOOL_LISTENING={"../assets/media/961cad02c552a02243944781c465b7d4fa53f7f8ce3970f29db022f8d4928f3a.mp3":[{"id":"PPT_961cad02c552a022","audioId":"PPT_961cad02c552a022","title":"Book 3 · Unit 8 · RW · READING 2","subtitle":"READING 2 · source slide 98","duration":215.82,"cues":[{"start":0,"end":3.46,"text":"What has happened to the dream of a better life?","coverage":1},{"start":5.08,"end":7.68,"text":"In almost every country and every culture,","coverage":1},{"start":8.02,"end":12.26,"text":"parents work hard to try to give their children a better life than they had.","coverage":1},{"start":13,"end":15.3,"text":"For decades following the Second World War,","coverage":1},{"start":15.76,"end":19.22,"text":"this dream became a reality in many countries around the world.","coverage":1},{"start":19.8,"end":23.86,"text":"Possibly the best example is the Japanese economic miracle.","coverage":1},{"start":24.66,"end":32.82,"text":"Thanks to a high rate of economic growth from the 1960s to the 1980s, it developed into one of the world's strongest economies.","coverage":1},{"start":33.72,"end":34.7,"text":"Yet in Japan,","coverage":1},{"start":35.02,"end":36.64,"text":"as in other developed countries,","coverage":1},{"start":37.22,"end":43.84,"text":"many people today are not able to enjoy a higher or even the same standard of living as their parents did.","coverage":1},{"start":44.52,"end":45.48,"text":"What has happened?","coverage":1},{"start":46.16,"end":50.32,"text":"Why do many people feel poorer than they were ten or 20 years ago?","coverage":1},{"start":51.1,"end":52.98,"text":"The answer is complicated,","coverage":1},{"start":53.5,"end":55.66,"text":"and every country tells a different story.","coverage":1},{"start":55.66,"end":59.26,"text":"The world's largest economy, the United States,","coverage":1},{"start":59.62,"end":60.82,"text":"provides a good example.","coverage":1},{"start":61.76,"end":65.72,"text":"One key factor which influences the standard of living is expenditure,","coverage":1},{"start":66.2,"end":68.9,"text":"which is the money you spend on the things that you need.","coverage":1},{"start":69.54,"end":72,"text":"From 2000 until 2015,","coverage":1},{"start":72.84,"end":76.74,"text":"Americans spent approximately 20 % of their incomes on housing,","coverage":1},{"start":77.22,"end":78.82,"text":"about ten % on food,","coverage":1},{"start":79.28,"end":81.08,"text":"about eight % on transport,","coverage":1},{"start":81.42,"end":84.7,"text":"and around three % each on entertainment and health.","coverage":1},{"start":84.7,"end":87.74,"text":"But these costs have been rising steadily.","coverage":1},{"start":88.5,"end":94.14,"text":"They now must spend about 34 % on housing and 13 % on food.","coverage":1},{"start":95,"end":97.84,"text":"In the United States, as in many other countries,","coverage":1},{"start":98.34,"end":102.8,"text":"the expenditures that are rising the fastest are housing and healthcare.","coverage":1},{"start":103.78,"end":105.38,"text":"In many cities worldwide,","coverage":1},{"start":105.78,"end":110.36,"text":"there is a serious shortage of houses and apartments to buy or rent.","coverage":1},{"start":111.04,"end":117.84,"text":"Healthcare costs also continue to rise as medicine and hospital care have become more expensive.","coverage":1},{"start":118.78,"end":119.68,"text":"Most recently,","coverage":1},{"start":120.12,"end":123.54,"text":"there have also been significant increases in food prices.","coverage":1},{"start":124.66,"end":125.08,"text":"However,","coverage":1},{"start":125.66,"end":127.52,"text":"expenditures are only half the picture.","coverage":1},{"start":128.24,"end":130.48,"text":"The other half is the money people earn,","coverage":1},{"start":130.98,"end":131.82,"text":"their income.","coverage":1},{"start":132.62,"end":134.56,"text":"In the United States, in general,","coverage":1},{"start":134.88,"end":136.56,"text":"incomes have also gone up.","coverage":1},{"start":136.84,"end":137.92,"text":"See figure one.","coverage":1},{"start":138.44,"end":141.96,"text":"Yet not all incomes are increasing at the same rate.","coverage":1},{"start":142.68,"end":146.26,"text":"For many people, they have not increased as much as expenditures.","coverage":1},{"start":147.16,"end":150.44,"text":"This means that their buying power has decreased.","coverage":1},{"start":151.34,"end":154,"text":"Figure two shows this increase in inequality.","coverage":1},{"start":154.82,"end":160.36,"text":"It shows change in income by group from the bottom 20 % to the top 20%.","coverage":1},{"start":161.26,"end":163.7,"text":"The top line shows the highest five%.","coverage":1},{"start":164.46,"end":170.08,"text":"It is clear that the incomes of the higher income groups are rising the fastest.","coverage":1},{"start":170.96,"end":174.32,"text":"The incomes of the lower groups are rising more slowly.","coverage":1},{"start":175.08,"end":180.38,"text":"It is not surprising that they do not have a higher standard of living than their parents.","coverage":1},{"start":181.72,"end":182.48,"text":"In conclusion,","coverage":1},{"start":182.98,"end":186.62,"text":"the impact of economic forces is not the same for everyone.","coverage":1},{"start":187.38,"end":188.74,"text":"In the United States,","coverage":1},{"start":189.24,"end":193.08,"text":"rising prices have had the greatest impact on the people with lower incomes.","coverage":1},{"start":193.08,"end":196.52,"text":"They must pay more for necessities like food,","coverage":1},{"start":196.88,"end":198.96,"text":"health care, and especially housing.","coverage":1},{"start":199.4,"end":200.36,"text":"And as a result,","coverage":1},{"start":200.74,"end":202.64,"text":"they have less money for education,","coverage":1},{"start":203.1,"end":203.56,"text":"investment,","coverage":1},{"start":203.98,"end":204.58,"text":"and savings.","coverage":1},{"start":205.4,"end":209.98,"text":"This makes it harder for the next generation to move up the economic ladder.","coverage":1},{"start":210.78,"end":215.76,"text":"For them, the dream of a better life than their parents is still only a dream.","coverage":1}],"file":"a5c7b49ef80d866be9b2.js","track":0,"media":"../assets/media/961cad02c552a02243944781c465b7d4fa53f7f8ce3970f29db022f8d4928f3a.mp3"}],"../assets/media/ae0b0565008796a3f745915aa4987ac2be0c0c4b9a13fd21bc9b3ea0566f6825.mp3":[{"id":"PPT_ae0b0565008796a3","audioId":"PPT_ae0b0565008796a3","title":"Book 3 · Unit 8 · RW · READING 1","subtitle":"READING 1 · source slide 42","duration":253.02,"cues":[{"start":0,"end":2.38,"text":"How should you invest your money?","coverage":1},{"start":3.3,"end":7.1,"text":"Many people put their money in a bank because it is safe.","coverage":1},{"start":7.62,"end":8.1,"text":"However,","coverage":1},{"start":8.54,"end":11.54,"text":"the interest rate at most banks is quite low.","coverage":1},{"start":12.28,"end":13.1,"text":"As a result,","coverage":1},{"start":13.56,"end":17.76,"text":"some people choose to invest their money in stocks and shares instead,","coverage":1},{"start":18.38,"end":22.08,"text":"because they hope their money will grow faster that way.","coverage":1},{"start":22.46,"end":22.9,"text":"Yet,","coverage":1},{"start":23.26,"end":25.64,"text":"investing in stocks can be risky.","coverage":1},{"start":25.64,"end":28.72,"text":"If the value of the stocks goes down,","coverage":1},{"start":29.12,"end":31.08,"text":"you could lose a lot of money.","coverage":1},{"start":31.94,"end":37,"text":"Many experts say you should invest only what you can afford to lose.","coverage":1},{"start":37.96,"end":38.22,"text":"So,","coverage":1},{"start":38.72,"end":44.34,"text":"what are some alternative investments for people who can afford to take big risks?","coverage":1},{"start":45.24,"end":49.82,"text":"Gold and classic cars are both popular investments.","coverage":1},{"start":51.44,"end":55.06,"text":"Over time, gold has been a very good investment.","coverage":1},{"start":55.06,"end":58.94,"text":"Though the price has fluctuated in recent years.","coverage":1},{"start":59.86,"end":63.54,"text":"Between 2017 and 2020, for example,","coverage":1},{"start":64.3,"end":72.7,"text":"the price rose from $one ,200 an ounce to a peak of $two ,800 an ounce.","coverage":1},{"start":73.54,"end":75.88,"text":"Then, by the end of 2022,","coverage":1},{"start":76.54,"end":79.4,"text":"it had fallen to $one ,800.","coverage":1},{"start":80.28,"end":81.86,"text":"By 2023,","coverage":1},{"start":82.38,"end":85.46,"text":"it rose again to $one ,900.","coverage":1},{"start":86.66,"end":89.38,"text":"If you are thinking about investing in gold,","coverage":1},{"start":89.94,"end":93.56,"text":"you may want to consider one famous investor's advice.","coverage":1},{"start":94.74,"end":95.64,"text":"Warren Buffett,","coverage":1},{"start":95.98,"end":98.12,"text":"one of the richest men in the world,","coverage":1},{"start":98.74,"end":100.76,"text":"dislikes gold as an investment.","coverage":1},{"start":101.74,"end":109.04,"text":"He points out that, historically, the stock market has brought in significantly higher returns than gold.","coverage":1},{"start":109.98,"end":118.6,"text":"He also says it is better for society if you use your money for something productive rather than have it sitting in a bank.","coverage":1},{"start":119.88,"end":124.34,"text":"While gold and stocks are both investment options in the long term,","coverage":1},{"start":124.9,"end":129.44,"text":"some people prefer investments that they can use and enjoy now.","coverage":1},{"start":129.92,"end":136.54,"text":"For these people, classic cars are one way to have fun and make lots of money.","coverage":1},{"start":137.28,"end":137.86,"text":"In fact,","coverage":1},{"start":138.28,"end":140.68,"text":"over the last 30 or 40 years,","coverage":1},{"start":141.1,"end":148.6,"text":"the value of some classic cars has risen far more than that of gold or other investments like houses.","coverage":1},{"start":149.86,"end":150.84,"text":"As an example,","coverage":1},{"start":151.34,"end":166.88,"text":"a 1972 Ferrari Dino 246 GT cost around $13 ,000 in 1980, but was worth as much as $370 ,000 in 2023.","coverage":1},{"start":168.18,"end":175.82,"text":"A man in Tennessee bought the Aston Martin DB5, which was used in two of the James Bond films.","coverage":1},{"start":176.76,"end":181.64,"text":"This car cost just $seven ,000 in 1980,","coverage":1},{"start":182.46,"end":187.56,"text":"but sold in 2010 for an incredible $four .one","coverage":1},{"start":187.56,"end":188.32,"text":"million.","coverage":1},{"start":189.34,"end":193.84,"text":"That is an incredible 20 ,000 % increase.","coverage":1},{"start":194.92,"end":200.88,"text":"But neither of these cars compares to what is perhaps the best investment ever.","coverage":1},{"start":202.04,"end":210.86,"text":"A 1955 Mercedes -Benz 300 SL cost about $36 ,000 in 1980,","coverage":1},{"start":211.6,"end":212.64,"text":"but is worth about $three ,000 in 2013.","coverage":1},{"start":212.66,"end":216.92,"text":"About $143 million now.","coverage":1},{"start":218.28,"end":218.94,"text":"In sum,","coverage":1},{"start":219.46,"end":224.04,"text":"the prospect of making lots of money through investing is very exciting.","coverage":1},{"start":224.76,"end":229.08,"text":"But one must never forget that investing is a risky business.","coverage":1},{"start":230.02,"end":233.2,"text":"Gold prices rise, but they also fall.","coverage":1},{"start":233.92,"end":236.68,"text":"The classic car market also fluctuates,","coverage":1},{"start":237.1,"end":241.6,"text":"and it is expensive to keep these cars in excellent condition.","coverage":1},{"start":242.66,"end":244.92,"text":"If you are clever and lucky,","coverage":1},{"start":245.42,"end":247.18,"text":"you may make a big profit.","coverage":1},{"start":247.94,"end":248.66,"text":"But remember,","coverage":1},{"start":249.28,"end":249.82,"text":"there are","coverage":1},{"start":249.82,"end":250.22,"text":"no","coverage":1},{"start":250.22,"end":250.98,"text":"guarantees.","coverage":1}],"file":"a67b53fb96d5e111739b.js","track":0,"media":"../assets/media/ae0b0565008796a3f745915aa4987ac2be0c0c4b9a13fd21bc9b3ea0566f6825.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 What happens when a country’s economy is in trouble? People may stop spending on luxury activities, choose cheaper products and feel worried.","slide":4,"shape":"15","bookPage":"170"},{"text":"2 How does this change when the economy improves? When the economy improves, people may relax and spend more money.","slide":4,"shape":"17","bookPage":"170"},{"text":"1 Which photos do you think show ‘economic indicators’? The restaurant, house sale, shop ties and building construction can all be indicators.","slide":6,"shape":"28","bookPage":"170"},{"text":"2 What can they tell us about the economy and about what people and businesses are doing? Buying or making more items may suggest a stronger economy; buying less may suggest a weaker one.","slide":6,"shape":"29","bookPage":"170"},{"text":"3 Do you believe economic indicators can predict what the economy will do in the future? Explain your answer. Indicators may show current conditions and predict short-term trends, but they may not predict the long term.","slide":6,"shape":"30","bookPage":"170"},{"text":"1  The economy includes how a country uses goods and money.","slide":13,"shape":"8","bookPage":"170"},{"text":"2  GDP measures the value of goods and services produced in a year.","slide":13,"shape":"9","bookPage":"170"},{"text":"3  Fast price increases are called inflation.","slide":13,"shape":"10","bookPage":"170"},{"text":"4  Many packages use cardboard boxes.","slide":13,"shape":"11","bookPage":"170"},{"text":"5  Areas outside a city are its suburbs.","slide":13,"shape":"12","bookPage":"170"},{"text":"Analysts look at some very unusual economic indicators to understand how the economy is doing. These include mosquito levels, the production of cardboard boxes and the construction of skyscrapers.","slide":16,"shape":"16","bookPage":"171"},{"text":"However, none of these alone is very reliable. A new high-tech tool that uses AI to analyze internet searches is better at determining the current and future health of the economy.","slide":17,"shape":"19","bookPage":"171"},{"text":"1  Restaurants are throwing away a lot of rubbish. ↑; people are eating out more and have money to spend.","slide":20,"shape":"6","bookPage":"171"},{"text":"2  Sales of boxes are increasing. ↑; companies expect higher sales and order more cardboard boxes.","slide":20,"shape":"7","bookPage":"171"},{"text":"3  Men are buying more ties. ↓; men may worry about losing jobs and want to look serious and hardworking.","slide":20,"shape":"8","bookPage":"171"},{"text":"1 Which economic indicator from the beginning of the video do you think is most useful? Why?The cardboard-box index may be useful because it connects expected sales to product packaging. Orders for packaging may reflect businesses’ expectations about sales.","slide":22,"shape":"16","bookPage":"171"},{"text":"2 What are two more unusual economic indicators that could tell us something about the economy? How do they suggest the economy is doing?Restaurant bookings and public-transport use could suggest whether people are spending and travelling more or less.","slide":23,"shape":"16","bookPage":"171"},{"text":"a interest rate: the percentage amount that you pay when you borrow money, or receive when you lend money, for a period of time.","slide":26,"shape":"14","bookPage":"172"},{"text":"b return: profit on money you have invested.","slide":26,"shape":"16","bookPage":"172"},{"text":"c stocks and shares: parts of a publicly-owned business which can be bought and sold as investments.","slide":27,"shape":"14","bookPage":"172"},{"text":"d invest: to put money in a bank, business, etc. to make a profit.","slide":27,"shape":"16","bookPage":"172"},{"text":"e value: how much money something could be sold for.","slide":28,"shape":"17","bookPage":"172"},{"text":"f afford: to have enough money to buy something.","slide":28,"shape":"19","bookPage":"172"},{"text":"g investment: something such as stocks or property which you buy in order to make a profit.","slide":28,"shape":"6","bookPage":"172"},{"text":"1 Can you give an example of a safe investment? What investments are risky?Government bonds may be safer; stocks and cryptocurrency can be risky.","slide":38,"shape":"17","bookPage":"172"},{"text":"2 Can you think of some usual and unusual ways to invest money? What are they?People may invest in property, jewellery, coins or art.","slide":38,"shape":"19","bookPage":"172"},{"text":"3 Who can afford to invest money in stocks? Who can afford to invest in classic cars?People with money left after basic needs may buy stocks. Classic cars generally require much more money.","slide":39,"shape":"18","bookPage":"172"},{"text":"Bank failures. Not discussed.","slide":52,"shape":"14","bookPage":"174"},{"text":"Two popular investments. Discussed.","slide":52,"shape":"15","bookPage":"174"},{"text":"The price of gold over time. Discussed.","slide":52,"shape":"16","bookPage":"174"},{"text":"The stock market in 2022. Not discussed.","slide":53,"shape":"14","bookPage":"174"},{"text":"Classic cars as an investment. Discussed.","slide":53,"shape":"15","bookPage":"174"},{"text":"The risks of investing. Discussed.","slide":53,"shape":"16","bookPage":"174"},{"text":"Paragraph 1  : two popular investments.","slide":65,"shape":"6","bookPage":"174"},{"text":"Paragraph 2  : the price of gold over time.","slide":65,"shape":"7","bookPage":"174"},{"text":"Paragraph 3  : classic cars as an investment.","slide":65,"shape":"8","bookPage":"174"},{"text":"Paragraph 4  : the risks of investing.","slide":65,"shape":"9","bookPage":"174"},{"text":"1 Approximately how much did gold cost per ounce in 2017? Approximately $1,200 an ounce.","slide":67,"shape":"14","bookPage":"174"},{"text":"2 In which year was the price of gold the highest? How much did it cost per ounce? 2020; $1,900 an ounce.","slide":67,"shape":"16","bookPage":"174"},{"text":"3 How much did a Ferrari Dino 246 GT cost in 1980? About $13,000.","slide":67,"shape":"6","bookPage":"174"},{"text":"4 What is a 1955 Mercedes-Benz 300SL worth now? About $143 million.","slide":67,"shape":"8","bookPage":"174"},{"text":"5 How much did the Aston Martin used in the James Bond films sell for in 2010? $4.1 million.","slide":68,"shape":"18","bookPage":"174"},{"text":"1 If you followed Warren Buffett’s advice, would you invest in the stock market or in gold? Why? The stock market. He says it has historically brought higher returns than gold.","slide":78,"shape":"17","bookPage":"174"},{"text":"2 Are classic cars a risky investment? Why / Why not? They can be risky and expensive to maintain. Future demand is uncertain, and cars must be kept in excellent condition.","slide":78,"shape":"19","bookPage":"174"},{"text":"3 What is the relationship between risk and return? Higher potential returns can involve greater risks. Taking a risk may bring a large gain, but it may also lead to a loss.","slide":79,"shape":"18","bookPage":"174"},{"text":"11. Paragraph A\nAnswer: vi","slide":82,"shape":"5","bookPage":null},{"text":"12. Paragraph B\nAnswer: vii","slide":83,"shape":"5","bookPage":null},{"text":"a savings: money that you put away, usually in a bank, for a later date.","slide":95,"shape":"17","bookPage":"175"},{"text":"b standard of living: how much money and comfort someone has.","slide":95,"shape":"19","bookPage":"175"},{"text":"c factor: one of the things that has an effect on a particular situation, decision, event, etc.","slide":95,"shape":"6","bookPage":"175"},{"text":"d expenditure: the total amount of money that a government or person spends on something.","slide":95,"shape":"8","bookPage":"175"},{"text":"e income: money that you earn by working, investing or producing goods.","slide":96,"shape":"17","bookPage":"175"},{"text":"f inequality: a situation in which not all groups in society have the same opportunities or money.","slide":96,"shape":"19","bookPage":"175"},{"text":"1 Do you think the standard of living in most developed countries has improved, got worse or stayed the same in the last 20 years? It depends on the country. In some developed countries, living standards continue to rise, but in many others they have remained the same or got worse.","slide":98,"shape":"15","bookPage":"176"},{"text":"2 What do you think is the biggest expense for most people? The biggest expense is probably rent or paying for a place to live.","slide":98,"shape":"17","bookPage":"176"},{"text":"Do you think the standard of living in most developed countries has improved, got worse or stayed the same in the last 20 years? Living standards: Many people feel poorer than they did 10 or 20 years ago.","slide":109,"shape":"15","bookPage":"176"},{"text":"What do you think is the biggest expense for most people? Biggest expense: Housing.","slide":109,"shape":"17","bookPage":"176"},{"text":"b The article explains the effects of economic factors on groups from different income levels.","slide":124,"shape":"13","bookPage":"176"},{"text":"1 a Rapid economic growth in Japan slowed down in the 1980s.","slide":127,"shape":"15","bookPage":"176"},{"text":"2 b Many Americans now spend about a third of their income on housing.","slide":127,"shape":"17","bookPage":"176"},{"text":"3 a Median household income in the US has increased steadily since 1985.","slide":127,"shape":"6","bookPage":"176"},{"text":"4 b US median household income has increased the fastest at the highest income level.","slide":127,"shape":"8","bookPage":"176"},{"text":"5 a Income inequality is increasing in the United States.","slide":128,"shape":"19","bookPage":"176"},{"text":"1 What is an example of countries that became richer in the decades following the Second World War? Japan, the United States, West Germany, France and Italy.","slide":139,"shape":"19","bookPage":"178"},{"text":"2 How can a person ‘move up the economic ladder’? What challenges do people at lower income levels have? People need access to education and healthcare. Lower-income people may struggle to pay for rent, food and clothing and may need jobs to support families, leaving less time to study.","slide":139,"shape":"21","bookPage":"178"},{"text":"3 Figure 1 gives information about median household income. Is there other information that it cannot give you? Median is the middle value, so Figure 1 cannot show how far above or below the median people are. Figure 2 shows the differences between income groups.","slide":140,"shape":"20","bookPage":"178"},{"text":"1 economy: the system by which a country produces and uses goods and money. economic: relating to money, industry or trade.","slide":161,"shape":"14","bookPage":"178"},{"text":"2 finance: the control of how large amounts of money should be spent. financial: relating to money or how money is managed.","slide":161,"shape":"16","bookPage":"178"},{"text":"3 wealth: a large amount of money or valuable possessions that somebody has. wealthy: having lots of money or possessions; rich.","slide":161,"shape":"6","bookPage":"178"},{"text":"4 poverty: the condition of being extremely poor. poor: having very little money or few possessions.","slide":162,"shape":"17","bookPage":"178"},{"text":"5 value: how much money something could be sold for. valuable: worth a lot of money.","slide":162,"shape":"19","bookPage":"178"},{"text":"6 employment: the fact of somebody being paid to work for a company or organization. employed: working for a company that pays you a wage.","slide":162,"shape":"6","bookPage":"178"},{"text":"7 profession: a type of work that needs special training or education. professional: relating to work that needs special training or education.","slide":163,"shape":"17","bookPage":"178"},{"text":"8 inequality: the unfair situation in society when some people have more opportunities, money, etc. than other people. unequal: different size, level or amount.","slide":163,"shape":"19","bookPage":"178"},{"text":"noun\nadjective\n1 economy (n): the system by which a country produces and uses goods and money\neconomic (adj): relating to money, industry or trade.\n2 finance (n): the control of how large amounts of money should be spent\nfinancial (adj): relating to money or how money is managed.\n3 wealth (n): a large amount of money or valuable possessions that somebody has\nwealthy (adj): having lots of money or possessions; rich.\n4 poverty (n): the condition of being extremely poor\npoor (adj): having very little money or few possessions.","slide":164,"shape":"12","bookPage":"178"},{"text":"noun\nadjective\n5 value (n): how much money something could be sold for\nvaluable (adj): worth a lot of money.\n6 employment (n): the fact of somebody being paid to work for a company or organization\nemployed (adj): working for a company that pays you a wage.\n7 profession (n): a type of work that needs special training or education\nprofessional (adj): relating to work that needs special training or education.\n8 inequality (n): the unfair situation in society when some people have more opportunities, money, etc. than other people\nunequal (adj): different size, level or amount.","slide":165,"shape":"12","bookPage":"178"},{"text":"8  In developed countries, economic inequality is increasing, with the rich becoming richer\nand the poor becoming poorer.","slide":169,"shape":"6","bookPage":"179"},{"text":"1 The top world markets for athletic shoes are China and the United States.","slide":179,"shape":"14","bookPage":"179"},{"text":"2 I was not satisfied with my purchase, so I returned the item to the shop.","slide":179,"shape":"16","bookPage":"179"},{"text":"3 The median income of Americans has increased steadily since the 1980s.","slide":180,"shape":"14","bookPage":"179"},{"text":"4 A recent fashion trend for women is shoes with extremely high heels.","slide":180,"shape":"16","bookPage":"179"},{"text":"5 The company failed because there was not enough demand for the products it was selling.","slide":181,"shape":"17","bookPage":"179"},{"text":"6 Most of the company’s revenue comes from online sales.","slide":181,"shape":"19","bookPage":"179"},{"text":"7 Prices go up when there is not enough supply of a product or service that people want.","slide":181,"shape":"6","bookPage":"179"},{"text":"Sales were twenty units in January. They reached thirty in February. There was an increase of ten units.","slide":186,"shape":"6","bookPage":null},{"text":"The seller could consider a lower price for the remaining vegetables. This might help customers afford a purchase before the stall closes.","slide":187,"shape":"6","bookPage":null},{"text":"The practice data show an increase in sales.","slide":187,"shape":"9","bookPage":null},{"text":"11. A low price may leave out necessary equipment.\nAnswer: B","slide":193,"shape":"5","bookPage":null},{"text":"12. Local repair possibilities are considered.\nAnswer: B","slide":193,"shape":"8","bookPage":null},{"text":"11. Paragraph A\nAnswer: v","slide":196,"shape":"5","bookPage":null},{"text":"12. Paragraph B\nAnswer: iii","slide":196,"shape":"8","bookPage":null},{"text":"Sales began at ten units. They rose sharply to thirty in the second month. They then fell to twenty. The final figure was still ten units above the start.","slide":202,"shape":"6","bookPage":null},{"text":"The figures began at forty units. They fell to twenty in the second period. They returned to forty in the third. The final figure was equal to the first.","slide":202,"shape":"9","bookPage":null},{"text":"1 What trend or ‘main idea’ does the graph show? Richer groups’ income rises faster than poorer groups’ income.","slide":206,"shape":"18","bookPage":"180"},{"text":"2 What is the meaning of the numbers on the left side of the graph? Income.","slide":206,"shape":"20","bookPage":"180"},{"text":"3 Which years are covered by the graph? 1960–2020; printed decade labels begin at 1970.","slide":206,"shape":"6","bookPage":"180"},{"text":"4 Why does the graph have six lines in different colours? What does each colour mean? Each colour represents a different income level, from the lowest 20% to the highest 5%.","slide":207,"shape":"18","bookPage":"180"},{"text":"5 During what period did median household income grow fastest for the richest Americans? 2010–2020.","slide":207,"shape":"20","bookPage":"180"},{"text":"6 Which coloured line is closest to the US Median Household income shown in Figure 1? The orange line.","slide":207,"shape":"6","bookPage":"180"},{"text":"b People in higher income groups make money from their investments. Tick","slide":211,"shape":"12","bookPage":"181"},{"text":"c People in lower income groups cannot afford a good education for their children so their children do not get jobs that pay well. Tick","slide":211,"shape":"14","bookPage":"181"},{"text":"d In the past, many people in lower and middle income groups had jobs in manufacturing, but many of these jobs have disappeared. Tick","slide":211,"shape":"6","bookPage":"181"},{"text":"1 The graph compares DVD and video streaming revenue. What do these terms mean? Which line on the graph represents which term?DVD revenue is income from selling or renting physical discs; streaming revenue comes from online viewing. The green line shows DVD revenue; the blue line shows film and TV downloaded or streamed revenue.","slide":214,"shape":"15","bookPage":"182"},{"text":"2 Which years are covered? 2010 to 2019.","slide":214,"shape":"17","bookPage":"182"},{"text":"3 What is the meaning of the numbers on the vertical axis? Millions of dollars.","slide":214,"shape":"6","bookPage":"182"},{"text":"4 In what year did revenue from sales of DVDs equal revenue from video streaming? 2014.","slide":215,"shape":"16","bookPage":"182"},{"text":"In 2010, revenue from DVD sales was worth about $16,000m, compared to only about $5,000m for video streaming. Estimated revenues for these two types of media show the exact opposite picture in 2019.","slide":219,"shape":"19","bookPage":"182"},{"text":"1 According to the graph, revenues from DVD sales and video streaming sales have moved in opposite directions. As revenue from sales of video streaming has risen, revenue from sales of DVDs has fallen.","slide":223,"shape":"18","bookPage":"182"},{"text":"2 What reason, or reasons, can you think of to explain the trend in Question 1?Physical stores declined, customers moved online, improved processing enabled higher-quality streaming, and streaming is convenient on any device.","slide":223,"shape":"20","bookPage":"182"},{"text":"3 Why is 2014 an important year in this graph? Streaming matched DVD sales, then overtook it after 2014.","slide":224,"shape":"19","bookPage":"182"},{"text":"1 Sales of DVDs rose sharply and then fell dramatically. a","slide":235,"shape":"6","bookPage":"183"},{"text":"2 DVD sales decreased slightly and then decreased sharply. f","slide":235,"shape":"7","bookPage":"183"},{"text":"3 The number of DVD sales did not change. d","slide":235,"shape":"8","bookPage":"183"},{"text":"4 DVD sales increased slightly and then increased sharply. c","slide":235,"shape":"9","bookPage":"183"},{"text":"5 At first, the number of DVDs sold did not change, but later this figure fluctuated. b","slide":235,"shape":"10","bookPage":"183"},{"text":"6 DVD sales fell slightly but did not change after that. e","slide":235,"shape":"11","bookPage":"183"},{"text":"a a sharp rise then a dramatic fall","slide":237,"shape":"18","bookPage":"183"},{"text":"b no change, then considerable fluctuation","slide":237,"shape":"20","bookPage":"183"},{"text":"c a slight/gradual increase, then a sharp/dramatic increase","slide":237,"shape":"6","bookPage":"183"},{"text":"d no change","slide":237,"shape":"8","bookPage":"183"},{"text":"e a gradual/slight decrease, and then no change","slide":238,"shape":"18","bookPage":"183"},{"text":"f a gradual/slight decrease, then a more dramatic/sharper decrease","slide":238,"shape":"20","bookPage":"183"},{"text":"1 Sales fell from 1.1 million to 1 million units, a decrease of 100,000 units.","slide":241,"shape":"17","bookPage":"184"},{"text":"2 Prices rose from around €5.00 to well over €10.00 — a rise of 100%.","slide":241,"shape":"19","bookPage":"184"},{"text":"3 From 2020 to 2024, prices decreased slightly, from €7.75 to €7.00.","slide":241,"shape":"6","bookPage":"184"},{"text":"Between 1985 and 2020, there was an increase of almost $50,000 in median income.","slide":244,"shape":"16","bookPage":"184"},{"text":"From 1985 until 2020, median US income rose steadily.","slide":244,"shape":"18","bookPage":"184"},{"text":"1 almost — nearly","slide":246,"shape":"17","bookPage":"184"},{"text":"2 more than — over","slide":246,"shape":"19","bookPage":"184"},{"text":"3 roughly — around / about / approximately","slide":246,"shape":"6","bookPage":"184"},{"text":"1 almost a hundred euros — c €99.99","slide":248,"shape":"17","bookPage":"184"},{"text":"2 roughly a thousand euros — a €1,014","slide":248,"shape":"19","bookPage":"184"},{"text":"3 approximately a million euros — b €996,001","slide":248,"shape":"6","bookPage":"184"},{"text":"1 less than a quarter of a million euros — €237,450","slide":250,"shape":"6","bookPage":"184"},{"text":"2 roughly half a million euros — €498,005","slide":250,"shape":"7","bookPage":"184"},{"text":"a Introductory sentence — explains what happened to sales in year one. Not used","slide":254,"shape":"17","bookPage":"185"},{"text":"b Introductory sentence — explains what can be seen on the graph. 1","slide":254,"shape":"19","bookPage":"185"},{"text":"c Main part of the paragraph — highlights key points. Not used","slide":254,"shape":"6","bookPage":"185"},{"text":"d Main part of the paragraph — explains all the changes. 2","slide":254,"shape":"8","bookPage":"185"},{"text":"e Concluding sentence — summarizes the changes, predicts what will happen in the future, or makes a final comment about the topic of the paragraph. 3","slide":255,"shape":"17","bookPage":"185"},{"text":"f Concluding sentence — explains the last trends on the graph. Not used","slide":255,"shape":"19","bookPage":"185"},{"text":"1 What trends can be seen in the graph?Sales of both phones increased at first, but later decreased. Phone A fell much earlier and more sharply.","slide":259,"shape":"16","bookPage":"185"},{"text":"2 How were sales of phone A and phone B similar over the period of the graph? How were they different?Both phones rose before declining. Phone A peaked at 200,000 in year 4, while phone B reached a higher peak of 250,000 in year 6; phone B remained above phone A from year 5 onwards.","slide":259,"shape":"18","bookPage":"185"},{"text":"Concluding paragraph: In conclusion, the impact of economic forces is not the same for everyone. In the United States, rising prices have had the greatest impact on lower income homes. They must pay more for necessities like food, healthcare and especially housing, and as a result, they have less money for education, investment and savings. This makes it harder for the next generation to move up the economic ladder. For them, the dream of a better life than their parents is still only a dream.","slide":265,"shape":"19","bookPage":"186"},{"text":"1 Thesis restatement: In conclusion, the impact of economic forces is not the same for everyone.","slide":266,"shape":"17","bookPage":"186"},{"text":"2 Transition phrase: In conclusion.","slide":266,"shape":"19","bookPage":"186"},{"text":"3 d the implications of the data. ‘This makes it harder for the next generation to move up the economic ladder.’ ‘For them, the dream of a better life than their parents is still only a dream.’","slide":266,"shape":"6","bookPage":"186"},{"text":"The series shows fictional monthly sales. The figure rose from twenty-one to thirty-five and then to forty-nine units. The final total was approximately fifty. Overall, sales increased throughout the period.","slide":270,"shape":"6","bookPage":null},{"text":"The figures compare fictional sales of two products. A rose from ten to thirty units, whereas B fell from forty to twenty. A finished ten units ahead of B. Overall, one product grew while the other declined.","slide":271,"shape":"6","bookPage":null}];
